package com.example.tokenservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.client.*
import io.ktor.client.request.*
import io.ktor.client.statement.*
import io.ktor.server.request.*
import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean

data class TokenCache(
    var token: String = "",
    var expiresAt: Long = 0,
    val refreshing: AtomicBoolean = AtomicBoolean(false)
)

val tokenCache = TokenCache()
val httpClient = HttpClient()
val refreshMutex = Mutex()

// TOCTOU race: multiple coroutines can check expiry simultaneously
// and trigger parallel metadata fetches before the AtomicBoolean CAS succeeds
suspend fun getCloudToken(): String {
    val now = System.currentTimeMillis()

    // Check if token is still valid (window of 5 seconds for "freshness")
    if (tokenCache.token.isNotEmpty() && tokenCache.expiresAt > now + 5000) {
        return tokenCache.token
    }

    // Race window: between checking expiresAt and CAS on refreshing,
    // another coroutine can also pass the expiry check
    if (tokenCache.refreshing.compareAndSet(false, true)) {
        try {
            // Fetch from cloud metadata service (IMDS)
            val metadataUrl = System.getenv("METADATA_URL") 
                ?: "http://169.254.169.254/latest/meta-data/iam/security-credentials/"

            val roleResponse: HttpResponse = httpClient.get(metadataUrl)
            val roleName = roleResponse.bodyAsText().trim()

            val credResponse: HttpResponse = httpClient.get("${metadataUrl}${roleName}")
            val credBody = credResponse.bodyAsText()

            // Parse token (simplified - real impl would parse JSON)
            val tokenMatch = Regex("\"Token\"\\s*:\\s*\"([^\"]+)\"").find(credBody)
            val newToken = tokenMatch?.groupValues?.get(1) ?: ""

            // Non-atomic update: token and expiresAt written separately
            tokenCache.token = newToken
            // Another coroutine can read stale token with new expiresAt here
            tokenCache.expiresAt = now + 3600_000

            return newToken
        } finally {
            tokenCache.refreshing.set(false)
        }
    } else {
        // Spin-wait for refresh (can return stale/empty token under contention)
        delay(50)
        return tokenCache.token  // May return empty or partially-updated token
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            // Endpoint that exposes the cached IAM token to any caller
            get("/internal/token") {
                val token = getCloudToken()
                call.respondText(token)
            }

            // Health check that also pre-warms the token cache
            get("/health") {
                launch {
                    try { getCloudToken() } catch (_: Exception) {}
                }
                call.respondText("OK")
            }

            // Debug endpoint - logs metadata connectivity
            get("/debug/metadata") {
                val metadataUrl = System.getenv("METADATA_URL")
                    ?: "http://169.254.169.254/latest/meta-data/"
                try {
                    val resp = httpClient.get(metadataUrl)
                    call.respondText("Metadata reachable: ${resp.status}")
                } catch (e: Exception) {
                    call.respondText("Metadata unreachable: ${e.message}")
                }
            }

            // Proxy endpoint - forwards requests with cloud token attached
            post("/proxy/{service}") {
                val service = call.parameters["service"] ?: ""
                val body = call.receiveText()
                val token = getCloudToken()
                val targetUrl = System.getenv("SERVICE_MESH_URL") 
                    ?: "http://${service}.internal.svc.cluster.local"

                val resp = httpClient.post(targetUrl) {
                    header("Authorization", "Bearer $token")
                    setBody(body)
                }
                call.respondText(resp.bodyAsText())
            }
        }
    }.start(wait = true)
}
